[DataContract]
public final class AVADAIReportCleanupContract extends SysOperationDataContractBase
{
    Query query;

    /// <summary>
    /// Query used to select AVADAIReportExportTable records. The dialog will allow users
    /// to add ranges on AVADAIReportExportTable.MetaDataExportDateTime and any other fields.
    /// </summary>
    /// <remarks>
    /// AifQueryTypeAttribute ensures the SysOperation dialog presents a query builder
    /// initialized with AVADAIReportExportTable as the root datasource.
    /// </remarks>
    [DataMemberAttribute]
    [AifQueryTypeAttribute('_query', tableStr(AVADAIReportExportTable))]
    public Query parmQuery(Query _query = query)
    {
        if (_query)
        {
            query = _query;
        }

        if (!query)
        {
            // Initialize a default query with AVADAIReportExportTable as the root datasource
            query = new Query();
            query.addDataSource(tableNum(AVADAIReportExportTable));
        }

        return query;
    }

    /// <summary>
    /// Basic validation. Ensures the root datasource is AVADAIReportExportTable
    /// so the dialog ranges are applied correctly.
    /// </summary>
    public boolean validate()
    {
        boolean isValid = super();

        if (query)
        {
            QueryBuildDataSource qbds = query.dataSourceNo(1);
            if (!qbds || qbds.table() != tableNum(AVADAIReportExportTable))
            {
                isValid = false;
                warning(strFmt("Query must be rooted at %1.", tableStr(AVADAIReportExportTable)));
            }
        }

        return isValid;
    }
}
